#!/usr/bin/env node
// Blog "Listen" audio, generated by hand (never inside `next build`, so a build needs no key and spends nothing).
//
//   npm run blog:audio -- --all --dry-run         plan and cost per language, no API calls
//   npm run blog:audio -- --all                   plan and cost, then asks before generating
//   npm run blog:audio -- kibui-masach            one post (each language it exists in)
//   npm run blog:audio -- --force kibui-masach    regenerate it even if nothing changed
//   npm run blog:audio -- --all --lang he         one language only
//
// The voice per post language is in content/blog/tts-voices.json; pronunciation fixes in
// content/blog/tts-lexicon.<lang>.json. Hebrew needs ELEVENLABS_API_KEY, English GOOGLE_TTS_API_KEY or
// GOOGLE_APPLICATION_CREDENTIALS (the npm script reads .env.tts.local). A language whose key is missing
// is skipped and reported. Each file is rendered to public/audio/blog/<lang>/<slug>.mp3 (gitignored, a
// local copy) and, with BLOB_READ_WRITE_TOKEN set, uploaded to Vercel Blob; content/blog/audio-manifest.json
// then holds the Blob URL. Without the token the manifest points at the local copy (dev only): rerun with
// the token to upload what was generated, at no API cost, before committing the manifest.

import { execFileSync, spawnSync } from "node:child_process";
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { dirname, join } from "node:path";
import { del, put } from "@vercel/blob";
import { createInterface } from "node:readline/promises";
import { fileURLToPath, pathToFileURL } from "node:url";
import { applyLexicon, audioHash, chunkText, needsAudio, speechFromMarkdown } from "../src/lib/blog-audio-text.ts";
import { missingKey, synthesize } from "./tts-providers.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const BLOG = join(ROOT, "content/blog");
const MANIFEST = join(BLOG, "audio-manifest.json");
const OUT_DIR = join(ROOT, "public/audio/blog");
const LANGS = ["he", "en"];
const PAUSE_SECONDS = 0.4; // between chunks

function parseArgs(argv) {
  const opts = { all: false, dryRun: false, yes: false, langs: LANGS, force: new Set(), slugs: new Set() };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--all") opts.all = true;
    else if (a === "--dry-run") opts.dryRun = true;
    else if (a === "--yes" || a === "-y") opts.yes = true;
    else if (a === "--lang") opts.langs = [argv[++i]];
    else if (a === "--force") {
      const slug = argv[++i];
      if (!slug || slug.startsWith("--")) throw new Error("--force needs a slug");
      opts.force.add(slug);
      opts.slugs.add(slug);
    } else if (a.startsWith("-")) throw new Error(`unknown option ${a}`);
    else opts.slugs.add(a);
  }
  if (!opts.langs.every((l) => LANGS.includes(l))) throw new Error(`--lang must be one of ${LANGS.join(", ")}`);
  if (!opts.all && !opts.slugs.size) throw new Error("name one or more slugs, or pass --all");
  return opts;
}

const readJson = (file) => JSON.parse(readFileSync(file, "utf8"));
const mb = (bytes) => `${(bytes / 1024 / 1024).toFixed(1)} MB`;
const money = (n) => `$${n.toFixed(2)}`;
const kbps = (bitrate) => Number.parseInt(bitrate, 10) || 64;
const isRemote = (src) => /^https:\/\//.test(src || "");

/** Uploads under a path named by the hash, so it can be cached for a year, and deletes the file it replaces. */
async function upload(item, previous) {
  const { url } = await put(
    `blog-audio/${item.lang}/${item.slug}-${item.hash.slice(0, 8)}.mp3`,
    readFileSync(item.outFile),
    { access: "public", contentType: "audio/mpeg", addRandomSuffix: false, allowOverwrite: true, cacheControlMaxAge: 31536000 },
  );
  if (isRemote(previous) && previous !== url) await del(previous);
  return url;
}

function hasTool(name) {
  return spawnSync(name, ["-version"], { stdio: "ignore" }).status === 0;
}

/**
 * Decodes and joins the chunks with a short pause (they end on a paragraph), normalises loudness with
 * ffmpeg's two-pass loudnorm and limits peaks. Same target for every language.
 */
export function render(chunkFiles, outFile, output) {
  const n = chunkFiles.length;
  const inputs = ["-hide_banner", "-nostats", ...chunkFiles.flatMap((f) => ["-i", f])];
  const pads = chunkFiles.slice(0, -1).map((_, i) => `[${i}:a]apad=pad_dur=${PAUSE_SECONDS}[p${i}]`);
  const labels = chunkFiles.map((_, i) => (i < n - 1 ? `[p${i}]` : `[${i}:a]`)).join("");
  const joined = n === 1 ? "[0:a]anull" : `${pads.join(";")};${labels}concat=n=${n}:v=0:a=1`;
  const target = `I=${output.lufs}:TP=${output.truePeak}:LRA=${output.lra}`;
  const pass1 = spawnSync(
    "ffmpeg",
    [...inputs, "-filter_complex", `${joined},loudnorm=${target}:print_format=json`, "-f", "null", "-"],
    {
      encoding: "utf8",
    },
  );
  if (pass1.status !== 0) throw new Error(`ffmpeg measure failed: ${pass1.stderr.slice(-400)}`);
  const m = JSON.parse(pass1.stderr.slice(pass1.stderr.lastIndexOf("{"), pass1.stderr.lastIndexOf("}") + 1));
  const measured = `measured_I=${m.input_i}:measured_TP=${m.input_tp}:measured_LRA=${m.input_lra}:measured_thresh=${m.input_thresh}:offset=${m.target_offset}:linear=true`;
  // The limiter sits 1 dB under the target: MP3 encoding adds overshoot on peaky voices.
  const limit = (10 ** ((output.truePeak - 1) / 20)).toFixed(3);
  const pass2 = spawnSync(
    "ffmpeg",
    [
      "-y",
      ...inputs,
      "-filter_complex",
      `${joined},loudnorm=${target}:${measured},alimiter=limit=${limit}:level=false`,
      "-ar",
      String(output.sampleRate),
      "-ac",
      String(output.channels),
      "-c:a",
      "libmp3lame",
      "-b:a",
      output.bitrate,
      outFile,
    ],
    { encoding: "utf8" },
  );
  if (pass2.status !== 0) throw new Error(`ffmpeg encode failed: ${pass2.stderr.slice(-400)}`);
}

function duration(file, bytes, output) {
  try {
    const out = execFileSync("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", file], {
      encoding: "utf8",
    });
    return Number(out);
  } catch {
    return (bytes * 8) / (kbps(output.bitrate) * 1000);
  }
}

function writeManifest(manifest) {
  const sorted = Object.fromEntries(
    Object.keys(manifest)
      .sort()
      .map((k) => [k, manifest[k]]),
  );
  writeFileSync(MANIFEST, `${JSON.stringify(sorted, null, 2)}\n`);
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  const config = readJson(join(BLOG, "tts-voices.json"));
  const manifest = existsSync(MANIFEST) ? readJson(MANIFEST) : {};

  const plan = [];
  const found = new Set();
  for (const lang of opts.langs) {
    const voice = config.languages[lang];
    const lexicon = readJson(join(BLOG, `tts-lexicon.${lang}.json`));
    for (const file of readdirSync(join(BLOG, lang))
      .filter((f) => f.endsWith(".md"))
      .sort()) {
      const slug = file.replace(/\.md$/, "");
      if (!opts.all && !opts.slugs.has(slug)) continue;
      found.add(slug);
      const text = applyLexicon(speechFromMarkdown(readFileSync(join(BLOG, lang, file), "utf8"), lang).text, lexicon);
      const hash = audioHash(text, voice, config.output);
      const key = `${lang}/${slug}`;
      const outFile = join(OUT_DIR, lang, `${slug}.mp3`);
      const src = manifest[key]?.src;
      const current = !needsAudio(manifest[key], hash, isRemote(src) || existsSync(outFile), opts.force.has(slug));
      plan.push({ lang, slug, key, voice, text, hash, outFile, current, localOnly: current && !isRemote(src) });
    }
  }
  const unknown = [...opts.slugs].filter((s) => !found.has(s));
  if (unknown.length) throw new Error(`no post named ${unknown.join(", ")} in ${opts.langs.join("/")}`);

  // Plan and cost per language, before any API call.
  const todo = plan.filter((p) => !p.current);
  const skippedLangs = new Map();
  let totalCost = 0;
  console.log("Plan (estimates; list price before free tiers):");
  for (const lang of opts.langs) {
    const voice = config.languages[lang];
    const items = plan.filter((p) => p.lang === lang);
    const pending = items.filter((p) => !p.current);
    const chars = pending.reduce((sum, p) => sum + p.text.length, 0);
    const cost = (chars / 1000) * voice.pricePer1kChars;
    const minutes = chars / voice.charsPerMinute;
    const bytes = minutes * 60 * kbps(config.output.bitrate) * 125;
    const reason = pending.length ? missingKey(voice.provider) : null;
    if (reason) skippedLangs.set(lang, reason);
    else totalCost += cost;
    console.log(
      `  ${lang}  ${voice.provider} ${voice.model} · ${voice.voiceName || voice.voice}: ${items.length} posts, ` +
        `${pending.length} to generate, ${items.length - pending.length} up to date; ` +
        `${chars.toLocaleString()} chars ≈ ${money(cost)}, ~${Math.round(minutes)} min of audio, ~${mb(bytes)}` +
        (reason ? `  → SKIPPED: ${reason}` : ""),
    );
  }
  const runnable = todo.filter((p) => !skippedLangs.has(p.lang));
  const blob = Boolean(process.env.BLOB_READ_WRITE_TOKEN);
  const uploads = blob ? plan.filter((p) => p.localOnly) : [];
  console.log(blob ? "Files go to Vercel Blob." : "BLOB_READ_WRITE_TOKEN not set: files stay local (dev only).");
  if (uploads.length) console.log(`${uploads.length} generated post(s) to upload, no API cost.`);
  if (!todo.length && !uploads.length) return console.log("Nothing to generate: every selected post is up to date.");
  if (opts.dryRun) return console.log("Dry run: nothing generated.");
  if (!runnable.length && !uploads.length) throw new Error("Every language with work to do is missing its key.");

  if (runnable.length && !opts.yes) {
    if (!process.stdin.isTTY) throw new Error("Pass --yes to generate without a prompt.");
    const rl = createInterface({ input: process.stdin, output: process.stdout });
    const answer = await rl.question(`Generate ${runnable.length} post(s) for about ${money(totalCost)}? [y/N] `);
    rl.close();
    if (!/^y(es)?$/i.test(answer.trim())) return console.log("Cancelled; nothing generated.");
  }

  const ffmpeg = hasTool("ffmpeg");
  if (!ffmpeg) console.log("ffmpeg not found: chunks are joined frame by frame and loudness is NOT normalised.");
  mkdirSync(join(ROOT, "tmp"), { recursive: true });
  const failures = [];
  for (const item of runnable) {
    const tmp = mkdtempSync(join(ROOT, "tmp", "blog-audio-"));
    try {
      const chunks = chunkText(item.text, item.voice.limit.max, item.voice.limit.unit);
      const files = [];
      for (const [i, chunk] of chunks.entries()) {
        const file = join(tmp, `${String(i).padStart(3, "0")}.mp3`);
        writeFileSync(file, await synthesize(chunk, item.voice));
        files.push(file);
      }
      mkdirSync(dirname(item.outFile), { recursive: true });
      if (ffmpeg) render(files, item.outFile, config.output);
      else writeFileSync(item.outFile, Buffer.concat(files.map((f) => readFileSync(f))));
      const bytes = statSync(item.outFile).size;
      const seconds = duration(item.outFile, bytes, config.output);
      const previous = manifest[item.key]?.src;
      manifest[item.key] = {
        src: `/audio/blog/${item.lang}/${item.slug}.mp3`,
        duration: Math.round(seconds),
        bytes,
        hash: item.hash,
        provider: item.voice.provider,
        model: item.voice.model,
        voice: item.voice.voice,
        generatedAt: new Date().toISOString(),
      };
      // Written before the upload too, so an interrupted run or a failed upload never pays for the audio twice.
      writeManifest(manifest);
      if (blob) {
        manifest[item.key].src = await upload(item, previous);
        writeManifest(manifest);
      }
      console.log(`  ✓ ${item.key}  ${chunks.length} chunk(s), ${Math.round(seconds)} s, ${mb(bytes)}`);
    } catch (err) {
      failures.push(`${item.key}: ${err.message}`);
      console.log(`  ✗ ${item.key}: ${err.message}`);
    } finally {
      rmSync(tmp, { recursive: true, force: true });
    }
  }

  for (const item of uploads) {
    try {
      manifest[item.key].src = await upload(item, null);
      writeManifest(manifest);
      console.log(`  ↑ ${item.key}  uploaded`);
    } catch (err) {
      failures.push(`${item.key}: upload: ${err.message}`);
      console.log(`  ✗ ${item.key}: upload: ${err.message}`);
    }
  }

  console.log(
    `\nGenerated ${runnable.length - failures.length}, failed ${failures.length}, up to date ${plan.length - todo.length}.`,
  );
  for (const [lang, reason] of skippedLangs) console.log(`Skipped ${lang}: ${reason}`);
  const local = Object.keys(manifest).filter((k) => !isRemote(manifest[k].src));
  if (local.length) {
    console.log(
      `${local.length} manifest entr${local.length === 1 ? "y points" : "ies point"} at local files that are not deployed. ` +
        "Set BLOB_READ_WRITE_TOKEN and rerun to upload them before committing the manifest.",
    );
  }
  if (failures.length) process.exitCode = 1;
}

// Importable for checks; runs only when executed directly.
if (import.meta.url === pathToFileURL(process.argv[1] || "").href) {
  main().catch((err) => {
    console.error(`blog:audio: ${err.message}`);
    process.exit(1);
  });
}
